import{z as t,x as i,o as e,c as d,q as l,j as s,D as B,d as r,s as o,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"货币危机模型","description":"","frontmatter":{"title":"货币危机模型","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/currency-crisis-models.md","filePath":"econ/currency-crisis-models.md","lastUpdated":1791063341000}'),p={name:"econ/currency-crisis-models.md"};function m(T,a,u,D,C,c){const n=i("Mermaid");return e(),d("div",null,[a[2]||(a[2]=l('<h1 id="货币危机模型" tabindex="-1">货币危机模型 <a class="header-anchor" href="#货币危机模型" aria-label="Permalink to &quot;货币危机模型&quot;">​</a></h1><div class="epigraph"><p>钉住与扩张性国内信贷不能共存：储备有限，影子浮动汇率一旦穿过钉住，投机者一次买完剩下的储备，危机是时间的函数，不是情绪的函数。</p><footer>—— Krugman, A Model of Balance-of-Payments Crises, JMCB 1979；Flood and Garber 1984</footer></div><p><a href="/econ/international-risk-sharing">上一课</a>写日常分担失败。本课缺口是坏状态：钉住崩溃。三代模型下一课把第一代放进谱系；本课先钉 Krugman 第一代的机制，接到主干<a href="/econ/sudden-stop">突然停止</a>与三角，不重画 IS–LM。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定 \\(E\\)、资本开放、国内信贷持续扩张（为财政赤字融资）。储备随信贷漏出。若永远钉住，储备终将负——不可能。Krugman：存在崩溃时点 \\(T\\)，使得影子汇率（储备耗尽后的浮动汇率）在 \\(T\\) 等于钉住；此前无攻击，此时投机者一次买光剩余储备。缺口不是「投资者恐慌」，而是套利：延迟攻击会留下跳升的资本利得，提前攻击会亏。危机日期由基本面路径唯一（在第一代）。</p><p><span class="marginnote">数字实例：钉住 1 美元兑 8 元，信贷扩张让影子汇率每年爬 0.5，从 7 起步，两年后穿过 8——那一刻就是 \\(T\\)。影子价 7.8 时按 8 抢攻白亏 0.2；等过 \\(T\\) 才动手，储备已被买光只剩贬值后的存货。唯一不吃亏的时点是 \\(T\\) 本身。</span></p><p><span class="marginnote">影子汇率：若今天就浮动、货币路径仍按信贷规则走，\\(E\\) 会在哪。Salant–Henderson 的黄金投机是祖先：政府以固定价卖有限库存。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>货币需求 \\(M/E=L(i,Y)\\)，钉住时 \\(E\\) 固定，\\(M\\) 由储备加国内信贷。信贷按常数增长。浮动后 \\(E\\) 随 \\(M\\) 走。平滑粘贴：崩溃瞬间 \\(E\\) 不跳（否则未利用套利）。解出 \\(T\\)。与三角：钉住 + 开放资本 ⇒ 货币不独立；硬要独立信贷，放弃的是钉住，形式是危机。</p>',9)),(e(),s(A,null,{default:B(()=>[o(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PEG%5B%22%E9%92%89%E4%BD%8F%20E%22%5D%20--%3E%20RES%5B%22%E5%82%A8%E5%A4%87%E7%BC%93%E5%86%B2%22%5D%0A%20%20CRED%5B%22%E6%8C%81%E7%BB%AD%E6%89%A9%E5%BC%A0%E4%BF%A1%E8%B4%B7%22%5D%20--%3E%20LEAK%5B%22%E5%82%A8%E5%A4%87%E6%BC%8F%E5%87%BA%22%5D%0A%20%20SHAD%5B%22%E5%BD%B1%E5%AD%90%20E%20%E5%8D%87%E7%A9%BF%E9%92%89%E4%BD%8F%22%5D%20--%3E%20ATT%5B%22%E4%B8%80%E6%AC%A1%E6%80%A7%E4%B9%B0%E5%85%89%E5%82%A8%E5%A4%87%22%5D%0A%20%20ATT%20--%3E%20FLOAT%5B%22%E8%A2%AB%E8%BF%AB%E6%B5%AE%E5%8A%A8%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与原罪：第一代可以在无错配下发生，对象是储备。原罪把贬值的净值成本加上，改变政府是否愿守——那是第三代味道，下一课。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是有限库存加固定价格。与商品稳定储备同构。投机者不是非理性：他们在无利差时等待，在影子价格穿过时攻击。政策含义：要么停掉信贷扩张（财政 / 货币改革），要么提前浮动，要么资本管制（后课）拉长漏出时间。宣布「有足够储备」若信贷规则不变，只推迟 \\(T\\)。",-1)),a[6]||(a[6]=E("p",null,"与 UIP：第一代常在完美预见下写，没有 Fama 谜。加上不确定，攻击可以有随机时点，仍由基本面驱动，不是纯太阳黑子——太阳黑子是第二代。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"Flood–Garber 把 Krugman 写成线性货币模型，便于课堂解 \\(T\\)。经验：拉丁美洲 1980 年代更像第一代；1992 年 ERM、1997 亚洲更要后两代。")],-1)),a[8]||(a[8]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：平滑粘贴就是「崩的瞬间价格不跳」——若攻击那一刻汇率有跳变，就说明有人本可以在跳变前一刻买入白赚一笔，套利没做干净。把这条贴上，崩溃时点 \\(T\\) 才被唯一钉住；它是解这类有限库存模型的常用边界条件。")],-1)),(e(),s(A,null,{default:B(()=>[o(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%8A%95%E6%9C%BA%E8%80%85%E9%80%89%E6%94%BB%E5%87%BB%E6%97%B6%E7%82%B9%22%5D%20--%3E%20A%5B%22%E6%8F%90%E5%89%8D%E4%BA%8E%20T%20%E6%94%BB%E5%87%BB%22%5D%0A%20%20T%20--%3E%20B%5B%22%E6%8B%96%E5%88%B0%20T%20%E4%B9%8B%E5%90%8E%22%5D%0A%20%20T%20--%3E%20C%5B%22%E6%81%B0%E5%9C%A8%20T%20%E6%94%BB%E5%87%BB%22%5D%0A%20%20A%20--%3E%20AL%5B%22%E6%8C%89%E9%AB%98%E4%BA%8E%E5%BD%B1%E5%AD%90%E4%BB%B7%E4%B9%B0%E5%85%A5%EF%BC%9A%E4%BA%8F%22%5D%0A%20%20B%20--%3E%20BL%5B%22%E5%82%A8%E5%A4%87%E5%B7%B2%E8%A2%AB%E5%85%88%E5%8A%A8%E8%80%85%E4%B9%B0%E5%85%89%EF%BC%9A%E6%97%A0%E5%88%A9%E5%8F%AF%E5%9B%BE%22%5D%0A%20%20C%20--%3E%20CL%5B%22%E4%B8%80%E6%AC%A1%E4%B9%B0%E5%85%89%E5%89%A9%E4%BD%99%E5%82%A8%E5%A4%87%EF%BC%9A%E5%88%A9%E6%B6%A6%E6%81%B0%E5%A5%BD%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20CL%20--%3E%20S%5B%22%E5%B9%B3%E6%BB%91%E7%B2%98%E8%B4%B4%E6%88%90%E7%AB%8B%EF%BC%8C%E5%8D%B1%E6%9C%BA%E6%97%B6%E7%82%B9%20T%20%E8%A2%AB%E5%94%AF%E4%B8%80%E9%92%89%E4%BD%8F%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有危机写成储备算术。经常账户可持续、银行、或有负债可以在储备仍多时崩溃——第二、三代。下一课专门分代。不要用本课写做空某货币的操作。量化栏外汇微观不是 \\(T\\) 的公式。</p><p><span class="marginnote">常见误区：初学者容易把第一代危机读成「市场信心突然崩塌」的突发事件。实际上在第一代模型里，投机攻击是按基本面算出来的套利机会：信贷规则不变，\\(T\\) 就写在那条路径上；宣布「储备充足」改变不了路径，只能改变 \\(T\\) 出现的日期。</span></p><p>后课默认：第一代危机是不一致政策下的时机套利，影子汇率穿过钉住。三角被违反时，危机是形式之一。多重均衡与金融加速器留给三代课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>钉住 + 持续信贷扩张 ⇒ 储备有限，必破。</li><li>崩溃时点由影子汇率等于钉住决定；投机是套利。</li><li>改革规则或提前浮动，而不是口头「储备充足」。</li><li>无错配也可以有第一代危机。</li><li>出处：Krugman, <em>JMCB</em> 1979；Flood and Garber 1984；Salant–Henderson。</li></ul>',6))])}const F=t(p,[["render",m]]);export{h as __pageData,F as default};
